window.AP3D_CELL_MAN={"parts":[{"n":"Plasma membrane","s":"membrane","d":"Phospholipid bilayer with embedded proteins, shown as the translucent outer skin. Selectively permeable: gases and lipids diffuse through; ions, glucose and water need channels, carriers or pumps.","b":[-0.64397,0.0,-0.46178,0.644,1.60011,0.13544],"v":7002,"i":42000,"p":0,"x":42012,"c":"#b0b6c7","tr":0.45},{"n":"Cytoplasm (cytosol)","s":"membrane","d":"The gel-like interior \u2014 water, ions, enzymes, glucose \u2014 where glycolysis happens and the organelles sit.","b":[-0.64286,0.05303,-0.42252,0.57068,1.56321,0.16026],"v":4002,"i":24000,"p":126012,"x":150024,"c":"#a89478","tr":0.5},{"n":"Nuclear envelope","s":"nucleus","d":"Double membrane (outer + inner) around the nucleus; the outer layer is continuous with the rough ER.","b":[-0.34013,0.72355,-0.11916,0.21269,1.26783,0.45328],"v":6004,"i":36000,"p":198024,"x":234048,"c":"#6a49b5"},{"n":"Nuclear pores","s":"nucleus","d":"Protein gateways through both membranes \u2014 mRNA and ribosome subunits out, proteins and nucleotides in.","b":[-0.34284,0.7159,-0.12832,0.22302,1.27903,0.46158],"v":19718,"i":120000,"p":306048,"x":424356,"c":"#e8bf82"},{"n":"Nucleoplasm","s":"nucleus","d":"The fluid inside the nucleus, drawn translucent so you can see the chromatin and nucleolus.","b":[-0.26503,0.77856,0.14591,0.13206,0.98144,0.38612],"v":6002,"i":36000,"p":664356,"x":700368,"c":"#8f74d6","tr":0.35},{"n":"Chromatin (DNA)","s":"nucleus","d":"DNA wound around histone proteins \u2014 the instructions. Loose between divisions; condenses into chromosomes for mitosis.","b":[-0.28368,0.79282,-0.04605,0.12975,1.15034,0.42971],"v":15499,"i":89994,"p":772368,"x":865364,"c":"#8b62e1"},{"n":"Nucleolus","s":"nucleus","d":"Dense body where ribosomal RNA is transcribed and ribosome subunits are assembled.","b":[-0.12176,0.83232,0.15913,0.02654,0.98256,0.29206],"v":12500,"i":72000,"p":1045352,"x":1120352,"c":"#3a2570"},{"n":"Rough endoplasmic reticulum","s":"endomembrane","d":"Stacked, ribosome-studded membrane sacs continuous with the nuclear envelope. Makes proteins bound for secretion, membranes or lysosomes.","b":[-0.43763,0.49572,-0.03351,0.40099,1.5189,0.18442],"v":20074,"i":120000,"p":1264352,"x":1384796,"c":"#b25840"},{"n":"Ribosomes (bound)","s":"ribosomes","d":"Ribosomes docked on the rough ER, feeding new proteins straight into the ER lumen.","b":[-0.44,0.49871,-0.03358,0.40222,1.52097,0.18556],"v":32500,"i":135000,"p":1624796,"x":1819796,"c":"#9a0303"},{"n":"Ribosomes (free)","s":"ribosomes","d":"Free ribosomes make the proteins that stay inside the cell.","b":[-0.34227,0.72404,-0.12361,0.21072,1.27219,0.45029],"v":4634,"i":24000,"p":2089796,"x":2117600,"c":"#9a0303"},{"n":"Smooth endoplasmic reticulum","s":"endomembrane","d":"Tubular ER without ribosomes: lipid and steroid synthesis, drug detoxification (liver), calcium storage (muscle).","b":[-0.59046,0.84356,-0.11465,-0.35462,1.24812,0.24252],"v":3992,"i":24000,"p":2165600,"x":2189552,"c":"#7099ac"},{"n":"Golgi apparatus","s":"endomembrane","d":"Stack of curved cisternae: proteins arrive from the ER at the cis face, are modified and sorted, and leave in vesicles from the trans face.","b":[0.22551,0.49742,-0.10977,0.51853,0.87217,0.15863],"v":8994,"i":54000,"p":2237552,"x":2291516,"c":"#dc7d4f"},{"n":"Mitochondria","s":"energy","d":"Double-membraned powerhouses: the inner membrane folds into cristae that run the electron-transport chain and make most of the cell's ATP. They carry their own DNA.","b":[-0.33203,0.21066,-0.06808,0.14939,0.50503,0.05504],"v":14007,"i":83994,"p":2399516,"x":2483560,"c":"#492c07"},{"n":"Lysosomes","s":"digestion","d":"Acidic sacs of hydrolytic enzymes: digest worn-out organelles, engulfed bacteria and debris.","b":[-0.23598,0.30086,-0.00788,-0.12527,0.40762,0.05961],"v":7012,"i":42000,"p":2651548,"x":2693620,"c":"#b9a27c"},{"n":"Peroxisomes","s":"digestion","d":"Break down fatty acids and detoxify hydrogen peroxide with catalase.","b":[-0.11323,0.12356,-0.05884,0.04048,0.29355,0.02332],"v":3012,"i":18000,"p":2777620,"x":2795692,"c":"#647ec5"},{"n":"Centrioles","s":"cytoskeleton","d":"Two barrels of nine microtubule triplets at right angles \u2014 the centrosome that organizes microtubules and the mitotic spindle.","b":[-0.36514,0.48423,0.01341,-0.27119,0.568,0.1338],"v":8063,"i":47994,"p":2831692,"x":2880072,"c":"#e6b246"},{"n":"Microtubules","s":"cytoskeleton","d":"Hollow tubulin rods radiating from the centrosome: tracks for motor proteins and the spindle that separates chromosomes.","b":[-0.49338,0.22053,-0.06688,0.22836,0.82292,0.25249],"v":4015,"i":23994,"p":2976060,"x":3000152,"c":"#e6b246"},{"n":"Cytoskeleton (filaments)","s":"cytoskeleton","d":"Actin microfilaments and intermediate filaments: cell shape, movement, and anchoring the organelles in place.","b":[-0.60482,0.15572,-0.19239,0.45069,1.30252,-0.02967],"v":22116,"i":135000,"p":3048140,"x":3180836,"c":"#4d587d"}],"tris":375992,"bytes":3450836,"credit":"Eukaryotic Cell Cross Section by dav169 (Sketchfab), CC BY 4.0"};window.AP3D_CELL_B64="";